package com.wattscape.asset;
import com.wattscape.audit.AuditEvent; import com.wattscape.audit.AuditEventRepository; import com.wattscape.building.BuildingRepository; import com.wattscape.common.ApiException; import com.wattscape.floor.FloorRepository; import com.wattscape.identity.TenantContext; import com.wattscape.room.RoomRepository; import com.wattscape.site.SiteService; import com.wattscape.twin.TwinEdge; import com.wattscape.twin.TwinEdgeRepository; import com.wattscape.twin.TwinNode; import com.wattscape.twin.TwinNodeRepository; import org.slf4j.MDC; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; import java.util.UUID;
@Service public class AssetService {
 private final AssetRepository assets; private final SiteService sites; private final TenantContext tenant; private final FloorRepository floors; private final BuildingRepository buildings; private final RoomRepository rooms; private final AuditEventRepository audit; private final TwinNodeRepository nodes; private final TwinEdgeRepository edges;
 public AssetService(AssetRepository a,SiteService s,TenantContext t,FloorRepository f,BuildingRepository b,RoomRepository r,AuditEventRepository au,TwinNodeRepository n,TwinEdgeRepository e){assets=a;sites=s;tenant=t;floors=f;buildings=b;rooms=r;audit=au;nodes=n;edges=e;}
 @Transactional(readOnly=true) public List<AssetDtos.AssetResponse> list(UUID siteId,Authentication auth){var site=sites.requireSite(siteId,auth);return assets.findAllBySiteIdAndOrganizationIdOrderByName(siteId,site.getOrganizationId()).stream().map(AssetDtos.AssetResponse::from).toList();}
 @Transactional public AssetDtos.AssetResponse create(UUID siteId,AssetDtos.CreateAssetRequest req,Authentication auth){var member=tenant.requireRole(auth,"Organization Owner","Organization Admin","Site Admin","Facilities Operator");var site=sites.requireSite(siteId,auth);var org=site.getOrganizationId();var floor=floors.findByIdAndOrganizationId(req.floorId(),org).orElseThrow(()->ApiException.badRequest("Floor does not belong to this site"));if(buildings.findByIdAndOrganizationIdAndSiteId(floor.getBuildingId(),org,siteId).isEmpty())throw ApiException.badRequest("Floor does not belong to this site");if(req.roomId()!=null){var room=rooms.findByIdAndSiteIdAndOrganizationId(req.roomId(),siteId,org).orElseThrow(()->ApiException.badRequest("Room does not belong to this site"));if(!room.getFloorId().equals(req.floorId()))throw ApiException.badRequest("Room and asset must reference the same floor");}if(assets.existsByOrganizationIdAndSourceId(org,req.sourceId()))throw ApiException.conflict("An asset with this source ID already exists in the organization");Asset a=assets.save(new Asset(org,siteId,req.floorId(),req.roomId(),req.systemName(),req.assetClass(),req.name().trim(),req.sourceId().trim(),req.manufacturer(),req.model(),req.serial(),req.commissionDate(),req.criticality()==null?"medium":req.criticality(),req.powerKw(),req.waterFlowLpm()));TwinNode assetNode=nodes.save(new TwinNode(org,siteId,"asset",a.getName(),"asset:"+a.getId()));UUID parentId;if(req.roomId()!=null) parentId=nodes.findAllBySiteIdAndOrganizationIdOrderByKindAscNameAsc(siteId,org).stream().filter(n0->n0.getKind().equals("space")&&n0.getSourceId().equals("room:"+req.roomId())).map(TwinNode::getId).findFirst().orElseThrow(()->ApiException.conflict("Twin room node is not provisioned"));else parentId=nodes.findAllBySiteIdAndOrganizationIdOrderByKindAscNameAsc(siteId,org).stream().filter(n0->n0.getKind().equals("floor")&&n0.getSourceId().equals("floor:"+req.floorId())).map(TwinNode::getId).findFirst().orElseThrow(()->ApiException.conflict("Twin floor node is not provisioned"));edges.save(new TwinEdge(org,parentId,assetNode.getId(),"located_in"));audit.save(new AuditEvent(org,member.getSubject(),"ASSET_CREATED","asset",a.getId(),"allowed",MDC.get("requestId"),java.util.Map.of()));return AssetDtos.AssetResponse.from(a);}
}
